    TreeNode<T> leftChild = node.getLeftChild();
    if (leftChild != null) {
        leftChild.setParent(node);
    }
    node.setLeftChild(parent);
    node.setParent(parent.getRightChild());
    parent.setRightChild(node);
    return parent;
}

