public String format(LoggingEvent event) {
    return conversionPattern.replaceAll("\\{([^}]*)\\}", (m) -> {
        String conversion = m.group(1);
        Object value = event.get(conversion);
        if (value == null) {
            throw new IllegalArgumentException("Conversion pattern contains unknown conversion specifier: " + conversion);
        }
        switch (conversion) {
            case "d":
                return LocalDate.ofEpochDay((Long) value).format(DateTimeFormatter.BASIC_ISO_DATE);
            case "t":
                return LocalTime.ofNanoOfDay((Long) value).format(DateTimeFormatter.ISO_TIME);
            case "p":
                return LocalDateTime.ofInstant((Instant) value, ZoneOffset.UTC).format(DateTimeFormatter.ISO_ZONED_DATE_TIME);
            default:
                throw new IllegalArgumentException("Unsupported conversion specifier: " + conversion);
        }
    });
}

