void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {

    // Create a copy of the graph to avoid modifying the original graph
    Graph<V,E> graph = new Graph<>(target);

    // Create a hashmap to store the bipartite graph with the vertices as the keys and the edges as the values
    Map<String, String> bipartiteGraph = new HashMap<>();

    // Iterate over the vertices in the original graph
    for (Vertex<V> vertex : graph.getVertices()) {

        // Get the color of the vertex
        String vertexColor = resultMap.get(vertex.getName());

        // If the vertex color is not null
        if (vertexColor != null) {

            // Get the edges of the vertex
            List<Edge<E>> edges = graph.getEdges(vertex);

            // Iterate over the edges
            for (Edge<E> edge : edges) {

                // Get the vertex at the other end of the edge
                Vertex<V> otherVertex = graph.getVertex(edge.getToVertexName());

                // Get the color of the other vertex
                String otherVertexColor = resultMap.get(otherVertex.getName());

                // If the colors of the two vertices are different
                if (!vertexColor.equals(otherVertexColor)) {

                    // Add the edge to the bipartite graph
                    bipartiteGraph.put(vertex.getName(), otherVertex.getName());
                }
            }
        }
    }

    // Add the vertices to the bipartite graph
    target.addAll(graph.getVertices());

    // Add the edges to the bipartite graph
    for (Edge<E> edge : graph.getEdges()) {
        target.add(edge);
    }

    // Return the generated bipartite graph
    return target;
}

