List<TimeRange> buildTimeRanges(long start, long end) {
    long duration = end - start;
    long splitDuration = duration / 2;
    long startTime = start;
    long endTime = start + splitDuration;
    List<TimeRange> timeRanges = new ArrayList<>();
    while (endTime <= end) {
        timeRanges.add(new TimeRange(startTime, endTime));
        startTime = endTime;
        endTime += splitDuration;
    }
    return timeRanges;
}

List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long diff = end - start;
    if (diff <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long currentStart = start;
        long currentEnd = Math.min(start + FETCH_DATA_DURATION, end);
        while (currentEnd < end) {
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            currentStart = currentEnd;
            currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        }
    }
    return timeRanges;
}

