public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null || byteLength == 0) {
        return this;
    }

    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("Input array is too small to be copied fully");
    }

    if (this.byteLength < this.byteArray.length + byteLength) {
        byte[] newByteArray = new byte[this.byteLength + byteLength];
        System.arraycopy(this.byteArray, 0, newByteArray, 0, this.byteLength);
        this.byteArray = newByteArray;
    }

    try {
        System.arraycopy(byteArrayValue, byteOffset, this.byteArray, this.byteLength, byteLength);
        this.byteLength += byteLength;
    } catch (ArrayIndexOutOfBoundsException ex) {
        throw new IllegalArgumentException("Input array is too small to be copied fully", ex);
    }

    return this;
}

