public static LinkedBuffer writeUTF8(String str, WriteSession session, LinkedBuffer lb) {
    int length = str.length();
    // Reserve space for the length prefix
    int prefixSize = length.stringSize();
    // For each character in the string
    for (int i = 0; i < length; i++) {
      char c = str.charAt(i);
      byte[] bytes = new byte[Character.charCount(c)];
      int byteCount = Character.toChars(c, bytes, 0);
      if (byteCount > 1) {
        // For multibyte characters, store a leading byte and subsequent bytes
        for (byte b : bytes[:byteCount-1]) {
          lb.writeByte(b & 0xBF);
        }
      }
      // Store the trailing byte
      lb.writeByte(bytes[byteCount-1] & 0x7F);
    }
    // Add the length of the string to the buffer
    lb.writeInt(length);
    return lb;
  }

