    if (str == null) {
        throw new NullPointerException("Cannot write null string to buffer.");
    }
    int size = (int)Math.ceil(str.length() * 1.5);
    if (lb == null) {
        lb = new LinkedBuffer(size);
    } else {
        lb.ensureRemaining(size);
    }
    UTF8StringEncoder encoder = UTF8StringEncoder.getInstance();
    ByteBuffer buf = lb.allocate(size);
    encoder.encode(str, buf);
    buf.flip();
    lb.add(buf);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
