    if (str.length() == 0) {
        return lb;
    }

    // Convert the string to a byte array
    byte[] bytes = str.toString().getBytes("UTF-8");

    // Loop through the byte array and write each byte to the LinkedBuffer
    for (byte b : bytes) {
        lb.writeByte(b);
    }

    return lb;
}

