    double yCenter = box.getCenter().getY();
    double xHalfWidth = box.getHalfWidth();
    double yHalfHeight = box.getHalfHeight();

    Box2D leftBox = new Box2D(new Point3D(xCenter - xHalfWidth, yCenter, 0),
                              new Dimension3D(xHalfWidth, yHalfHeight, 0));
    Box2D rightBox = new Box2D(new Point3D(xCenter + xHalfWidth, yCenter, 0),
