    double boxY = box.getY();

    double leftWidth = boxWidth / 2;
    double leftHeight = boxHeight;
    double leftX = boxX;
    double leftY = boxY;

    double rightWidth = boxWidth - leftWidth;
    double rightHeight = boxHeight;
    double rightX = boxX + leftWidth;
    double rightY = boxY;

    Box2D leftBox = new Box2D(leftX, leftY, leftWidth, leftHeight);
    Box2D rightBox = new Box2D(rightX, rightY, rightWidth, rightHeight);

    return new Pair<Box2D,Box2D>(leftBox, rightBox);
}

