private Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class) {
        return value.toString().charAt(0);
    } else if (type == Byte.class) {
        return (byte) value;
    } else if (type == Short.class) {
        return (short) value;
    } else if (type == Integer.class) {
        return (int) value;
    } else if (type == Long.class) {
        return (long) value;
    } else if (type == Float.class) {
        return (float) value;
    } else if (type == Double.class) {
        return (double) value;
    } else if (type == Boolean.class) {
        return (boolean) value;
    } else {
        throw new Exception("Invalid type: " + type.getName());
    }
}

public static Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null || value == null) {
        throw new IllegalArgumentException("Type and value cannot be null.");
    }

    if (type == Integer.class || type == int.class) {
        if (value instanceof Integer) {
            return Integer.valueOf((Integer) value);
        } else if (value instanceof Long) {
            return Integer.valueOf(((Long) value).intValue());
        } else if (value instanceof String) {
            return Integer.valueOf(Integer.parseInt((String) value));
        }
    } else if (type == Long.class || type == long.class) {
        if (value instanceof Integer) {
            return Long.valueOf((Integer) value);
        } else if (value instanceof Long) {
            return Long.valueOf((Long) value);
        } else if (value instanceof String) {
            return Long.valueOf(Long.parseLong((String) value));
        }
    } else if (type == Boolean.class || type == boolean.class) {
        if (value instanceof Boolean) {
            return Boolean.valueOf((Boolean) value);
        } else if (value instanceof String) {
            return Boolean.valueOf(Boolean.parseBoolean((String) value));
        }
    } else if (type == String.class) {
        return String.valueOf(value);
    }

    throw new IllegalArgumentException("Unsupported type for conversion: " + type.getName());
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class) {
        if (value instanceof String) {
            return ((String) value).charAt(0);
        } else if (value instanceof Number) {
            return (char) ((Number) value).shortValue();
        } else if (value instanceof Boolean) {
            return ((Boolean) value) ? '1' : '0';
        } else {
            throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
        }
    } else {
        throw new Exception("Unsupported type: " + type.getName());
    }
}

