private boolean unlink(ListNodeImpl<E> node) {
    // Check if the node is null
    if (node == null) {
        return false;
    }
    // Get the previous and next nodes of the node to be removed
    ListNodeImpl<E> prev = node.prev();
    ListNodeImpl<E> next = node.next();
    // If the next node is not null, set its previous node to the previous node of the node to be removed
    if (next != null) {
        next.setPrev(prev);
    }
    // If the previous node is not null, set its next node to the next node of the node to be removed
    if (prev != null) {
        prev.setNext(next);
    }
    // Set the previous and next nodes of the node to be removed to null
    node.setPrev(null);
    node.setNext(null);
    // Return true to indicate that the node was unlinked successfully
    return true;
}

