private String parseToken(final char[] terminators) {
String token = "";
int i = 0, terminatorIndex = 0;

while (i < terminators.length) {
  char ch = Character.toLowerCase(terminators[i]);
  if (ch == '"' || ch == '\'' || ch == '/') {
    token += String.valueOf(ch);
    i++;
  } else if (terminatorIndex < terminators.length) {
    token += parseToken(terminators, i, terminatorIndex);
    i++;
  }
}

return token;
}

private String parseToken(final char[] terminators, int offset, int terminatorIndex) {
String token = "";
while (offset < terminators.length) {
  char ch = Character.toLowerCase(terminators[offset]);
  if (terminatorIndex < terminators.length) {
    if (ch == terminators[terminatorIndex]) {
      offset++;
      terminatorIndex++;
    } else if (Character.isWhitespace(ch)) {
      offset++;
    } else {
      break;
    }
    token += parseToken(terminators, offset, terminatorIndex);
  }
}

return token;
}

