private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize variables
    List<Integer> suffixSum = new ArrayList<Integer>(bounds.size());
    long sum = 0;

    // Compute suffix sum
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }

    // Return result
    return Pair.of(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    Long sum = bounds.stream().mapToLong(i -> i).sum();
    List<Integer> suffixSumList = new ArrayList<>();
    for (Integer bound : bounds) {
        suffixSumList.add(sum - bound);
        sum -= bound;
    }
    return new Pair<List<Integer>, Long>(suffixSumList, sum);
}

