    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSumList.add(i, sum + bounds.get(i));
        sum += bounds.get(i);
    }
    return new Pair<>(suffixSumList, sum);
}

