    // Check if from and to are valid indices
    if (from < 0 || from >= arr.length || to < 0 || to >= arr.length) {
        throw new IllegalArgumentException("From and to must be valid indices");
    }

    // Check if from is less than or equal to to
    if (from > to) {
        throw new IllegalArgumentException("From must be less than or equal to to");
    }

    // Use a wrapper array to swap elements
    V[] wrapperArray = Arrays.copyOf(arr, arr.length);
    for (int i = from, j = to; i < j; ++i, --j) {
        V temp = wrapperArray[i];
        wrapperArray[i] = wrapperArray[j];
        wrapperArray[j] = temp;
    }

    // Assign the result to the original array
    arr = wrapperArray;
}

