public ByteVector putInt(final int intValue){
    int bytesNeeded = 32 - Integer.numberOfLeadingZeros(intValue);
    if (bytesNeeded < 0 || bytesNeeded > 8) {
        throw new IllegalArgumentException("Unsupported int value: " + intValue);
    }
    ensureCapacity(bytesNeeded);
    while (bytesNeeded > 0) {
        putByte((byte)(intValue >> (bytesNeeded - 1) * 8));
        bytesNeeded--;
    }
    return this;
}

