private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if all pairs of vertices in the set of vertices are connected in the graph
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.isConnected(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
 boolean isClique = true;
 for (V v1 : vertices) {
   for (V v2 : vertices) {
     if (v1 == v2) continue;
     if (!graph.adjacent(v1, v2)) {
       isClique = false;
       break;
     }
   }
   if (!isClique) break;
 }
 return isClique;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices cannot be null");
    }

    // Check if the graph is complete
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    boolean isClique = true;
    Set<V> visitedVertices = new HashSet<>();
    for (V v : vertices) {
        if (!visitedVertices.contains(v)) {
            boolean isConnectedToAllOthers = true;
            for (V u : vertices) {
                if (!u.equals(v) && !graph.connectedByEdge(v, u)) {
                    isConnectedToAllOthers = false;
                    break;
                }
            }
            if (!isConnectedToAllOthers) {
                isClique = false;
                break;
            }
            visitedVertices.add(v);
        }
    }
    return isClique;
}

public static <V, E> int calculateCliqueNumber(Graph<V, E> graph) {
    // calculate the maximum number of edges in a clique with n vertices
    // based on the well-known fact that a clique has maximum number of edges
    // when it has the maximum number of vertices
    int n = graph.getVertexCount();
    int maxEdgesInClique = (n * (n - 1)) / 2;

    // iterate over all possible subsets of the vertex set
    for (Set<V> vertices : Sets.powerSet(graph.getVertices())) {
        // calculate the number of edges in the subgraph induced by the current subset
        int numEdges = graph.calculateSubgraphEdges(vertices);

        // check if the subgraph with the current subset is a clique
        if (numEdges == maxEdgesInClique) {
            // return the size of the subset
            return vertices.size();
        }
    }
    // if no clique was found, return 0
    return 0;
}

