private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        int index = lowerBounds.size() - 1;
        while (index >= 0 && key.compareTo(lowerBounds.get(index)) > 0) {
            index = index - 1;
        }
        lowerBounds.add(index + 1, key);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {

        // Initialize a new list to store the lower bounds
        List<Integer> lowerBounds = new ArrayList<>(keys.size());

        // Iterate over the keys and compute the lower bound for each key
        for (int i = 0; i < keys.size(); i++) {
            if (i == 0) {
                lowerBounds.add(0);
            } else {
                Integer previousLowerBound = lowerBounds.get(i - 1);
                Integer previousKey = keys.get(i - 1);
                Integer currentKey = keys.get(i);
                if (currentKey > previousKey) {
                    lowerBounds.add(previousLowerBound);
                } else if (currentKey < previousKey) {
                    lowerBounds.add(previousLowerBound + 1);
                } else {
                    lowerBounds.add(previousLowerBound);
                }
            }
        }

        return lowerBounds;
    }

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        int lb = 0;
        for (int j = 0; j < i; j++) {
            if (keys.get(j) <= keys.get(i)) {
                lb++;
            }
        }
        lowerBounds.add(lb);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    // initialize an empty list to store the lower bounds
    List<Integer> lowerBounds = new ArrayList<>();

    // iterate over the keys
    for (K key : keys) {
      // get the index of the current key in the list
      int index = keys.indexOf(key);

      // check if the key is the first one in the list
      if (index == 0) {
        // if it is, the lower bound is the current index
        lowerBounds.add(index);
      } else {
        // otherwise, find the next higher key
        int nextHigher = keys.indexOf(key+1);

        // if the next higher key does not exist,
        // then the lower bound is the last index in the list
        if (nextHigher == -1) {
          lowerBounds.add(keys.size() - 1);
        } else {
          // otherwise, the lower bound is the next higher key minus 1
          lowerBounds.add(nextHigher - 1);
        }
      }
    }

    return lowerBounds;
  }

void pop(String descriptor) {
    // Check if the descriptor is a type descriptor
    if (descriptor.startsWith("L")) {
        // If it is a type descriptor, check if it has a generic type
        if (descriptor.contains("<")) {
            // If it has a generic type, check the number of arguments
            if (descriptor.split("<").length == 2) {
                // If it has one argument, pop a string value from the output frame stack
                outputFrameStack.pop();
            } else {
                // If it has multiple arguments, pop a list of values from the output frame stack
                outputFrameStack.popList();
            }
        } else {
            // If it does not have a generic type, pop a string value from the output frame stack
            outputFrameStack.pop();
        }
    } else {
        // If the descriptor is a method descriptor, check if it has an argument list
        if (descriptor.contains("(")) {
            // If it has an argument list, pop the arguments from the output frame stack
            String[] args = descriptor.substring(descriptor.indexOf("(") + 1, descriptor.indexOf(")")).split(",");
            for (String arg : args) {
                outputFrameStack.pop(arg);
            }
        } else {
            // If it does not have an argument list, do nothing
        }
    }
}

