        }
    }
    LinkedList<AbstractType> stack = getOutputFrame().getStack();
    for (int i = 0; i < length; i++) {
        AbstractType type = stack.pop();
        if (type.toString().equals(descriptor.charAt(length - i))) {
            return;
        }
    }
}

private void pop(final String descriptor) {
