private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    for (int i = 1; i < keys.size(); i++) {
        upperBounds.add(Math.min(keys.get(i - 1), keys.get(i)));
    }
    return upperBounds;
}

List<Integer> computeUpperBounds(List<K> keys) {

return keys.stream()
        .map(key -> Collections.frequency(keys, key) * key.hashCode())
        .collect(Collectors.toList());
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<Integer>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int upperBound = findMin(upperBounds, key);
        upperBounds.add(upperBound);
    }
    return upperBounds;
}

private int findMin(List<Integer> upperBounds, K key) {
    int lowerBound = 0;
    int upperBound = upperBounds.size() - 1;
    while (lowerBound <= upperBound) {
        int mid = (lowerBound + upperBound) / 2;
        K midKey = upperBounds.get(mid);
        if (midKey.compareTo(key) <= 0) {
            lowerBound = mid + 1;
        } else {
            upperBound = mid - 1;
        }
    }
    return upperBound;
}

std::vector<int> computeUpperBounds(const std::vector<K>& keys) {

// Initialize an empty list to store the upper bounds
std::vector<int> upperBounds;

// Iterate over the keys and find the minimum lower bound for each key
for (const auto& key : keys) {
    // Find the minimum lower bound for the current key
    int lowerBound = 0;
    for (const auto& existingKey : upperBounds) {
        if (key < existingKey) {
            lowerBound = existingKey;
            break;
        }
    }

    // Add the minimum lower bound to the upper bounds list
    upperBounds.push_back(key + lowerBound);
}

// Return the computed upper bounds
return upperBounds;
}

