                currentLowerBound = keys.get(j);
            }
        }
        upperBounds.add(currentLowerBound);
    }
    return upperBounds;
}

public static String encodeTemplateNames(String s) {
    StringBuffer output = new StringBuffer();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            output.append("%7B");
        } else if (c == '}') {
            output.append("%7D");
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

