public static String applyRelativePath(String path, String relativePath) {

  // Check if the path is null or empty
  if (path == null || path.isEmpty()) {
     throw new IllegalArgumentException("Path cannot be null or empty");
  }

  // Check if the relative path is null or empty
  if (relativePath == null || relativePath.isEmpty()) {
     return path;
  }

  // Split the path and the relative path into individual parts using the "/" delimiter
  String[] pathParts = path.split("/");
  String[] relativePathParts = relativePath.split("/");

  // Create a new array to hold the combined path parts
  String[] combinedPathParts = new String[pathParts.length + relativePathParts.length];

  // Copy the path parts to the new array
  System.arraycopy(pathParts, 0, combinedPathParts, 0, pathParts.length);

  // Copy the relative path parts to the new array, starting from the end of the path parts array
  System.arraycopy(relativePathParts, 0, combinedPathParts, pathParts.length, relativePathParts.length);

  // Join the combined path parts using the "/" delimiter
  return String.join("/", combinedPathParts);
}

public String applyRelativePath(String path, String relativePath) {
    StringBuilder builder = new StringBuilder();
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    for (int i = 0; i < relativePathParts.length; i++) {
        String part = relativePathParts[i];
        if (part.equals("..")) {
            if (i == 0) {
                throw new IllegalArgumentException(
                    "Relative path cannot contain '..' at start");
            }
            builder.delete(builder.lastIndexOf("/"), builder.length());
        } else if (!part.isEmpty()) {
            if (i > 0 && !pathParts[i - 1].isEmpty()) {
                builder.append("/");
            }
            builder.append(part);
        }
    }

    return builder.toString();
}

public static string applyRelativePath(string path, string relativePath) {
    string[] pathParts = path.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
    string[] relativePathParts = relativePath.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
    string outputPath = string.Empty;

    for (int i = 0; i < relativePathParts.Length; i++) {
        if (relativePathParts[i] == "..") {
            outputPath = pathParts[pathParts.Length - 1];
        } else {
            outputPath += string.Format("/{0}", relativePathParts[i]);
        }
    }

    return outputPath;
}

