int indexOfExtension(String filename){
    // Check if the filename is null or empty
    if (filename == null || filename.isEmpty()) {
        return -1;
    }

    // Find the last dot in the filename
    int lastDot = filename.lastIndexOf('.');

    // If the last dot is preceded by a directory separator, return -1
    if (lastDot > 0 && filename.charAt(lastDot - 1) == File.separatorChar) {
        return -1;
    }

    // Otherwise, return the index of the last dot
    return lastDot;
}

