boolean substringMatch(String str, int index, String substring) {
    if (str == null || substring == null) {
        return false;
    }
    int len = substring.length();
    if (index < 0 || index + len > str.length()) {
        return false;
    }
    for (int i = 0; i < len; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (index < 0 || index >= str.length()) {
        return false;
    }

    if (str instanceof String && substring instanceof String) {
        return ((String) str).substring(index, index + substring.length()).equals(substring);
    } else {
        for (int i = 0; i < substring.length(); i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}

