public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

       List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
       BufferedReader reader = new BufferedReader(new FileReader(file));

       String line;
       while ((line = reader.readLine()) != null) {

             String[] cols = line.split(",");
             if (cols.length < 4) {
                   continue;
             }

             // get thread id and sample events
             long threadId = Long.parseLong(cols[0]);
             List<SampledEvent> sampledEvents = new ArrayList<>();
             for (int i = 4; i < cols.length; i++) {
                   String[] eventData = cols[i].split(" ");
                   if (eventData.length < 3) {
                         continue;
                   }
                   SampledEvent event = new SampledEvent();
                   event.setThreadId(threadId);
                   event.setTimestamp(Long.parseLong(eventData[0]));
                   event.setEventType(eventData[1]);
                   if (eventData[2].equals("true")) {
                         event.setActive(true);
                   } else {
                         event.setActive(false);
                   }
                   sampledEvents.add(event);
             }

             // create thread snapshot
             ThreadSnapshot threadSnapshot = new ThreadSnapshot();
             threadSnapshot.setThreadId(threadId);
             threadSnapshot.setSampledEvents(sampledEvents);
             threadSnapshots.add(threadSnapshot);
       }

       reader.close();

       return threadSnapshots;
}

